import java.util.*;

class Solution {
    public int[] smallestRange(int[][] nums) {
        int k = nums.length;
        PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        int currentMax = Integer.MIN_VALUE;

        for (int listIndex = 0; listIndex < k; listIndex++) {
            int value = nums[listIndex][0];
            minHeap.offer(new int[]{value, listIndex, 0});
            currentMax = Math.max(currentMax, value);
        }

        int bestLeft = minHeap.peek()[0];
        int bestRight = currentMax;
        while (minHeap.size() == k) {
            int[] smallest = minHeap.poll();
            int currentMin = smallest[0];
            if (isBetter(currentMin, currentMax, bestLeft, bestRight)) {
                bestLeft = currentMin;
                bestRight = currentMax;
            }

            int nextIndex = smallest[2] + 1;
            int listIndex = smallest[1];
            if (nextIndex == nums[listIndex].length) {
                break;
            }
            int nextValue = nums[listIndex][nextIndex];
            minHeap.offer(new int[]{nextValue, listIndex, nextIndex});
            currentMax = Math.max(currentMax, nextValue);
        }
        return new int[]{bestLeft, bestRight};
    }

    private boolean isBetter(int left, int right, int bestLeft, int bestRight) {
        return right - left < bestRight - bestLeft
                || (right - left == bestRight - bestLeft && left < bestLeft);
    }
}

import java.util.*;

class Solution {
    public int[] smallestRange(int[][] nums) {
        int k = nums.length;
        List<int[]> merged = new ArrayList<>();
        for (int listIndex = 0; listIndex < k; listIndex++) {
            for (int value : nums[listIndex]) {
                merged.add(new int[]{value, listIndex});
            }
        }
        merged.sort(Comparator.comparingInt(a -> a[0]));

        int[] frequency = new int[k];
        int covered = 0;
        int bestLeft = 0;
        int bestRight = Integer.MAX_VALUE;
        int left = 0;

        for (int right = 0; right < merged.size(); right++) {
            int rightList = merged.get(right)[1];
            if (frequency[rightList]++ == 0) {
                covered++;
            }

            while (covered == k) {
                int rangeLeft = merged.get(left)[0];
                int rangeRight = merged.get(right)[0];
                if (isBetter(rangeLeft, rangeRight, bestLeft, bestRight)) {
                    bestLeft = rangeLeft;
                    bestRight = rangeRight;
                }

                int leftList = merged.get(left)[1];
                frequency[leftList]--;
                if (frequency[leftList] == 0) {
                    covered--;
                }
                left++;
            }
        }
        return new int[]{bestLeft, bestRight};
    }

    private boolean isBetter(int left, int right, int bestLeft, int bestRight) {
        return right - left < bestRight - bestLeft
                || (right - left == bestRight - bestLeft && left < bestLeft);
    }
}

class Solution {
    public int[] smallestRange(int[][] nums) {
        int bestLeft = 0;
        int bestRight = Integer.MAX_VALUE;

        for (int[] sourceList : nums) {
            for (int left : sourceList) {
                int right = left;
                boolean valid = true;
                for (int[] list : nums) {
                    int index = lowerBound(list, left);
                    if (index == list.length) {
                        valid = false;
                        break;
                    }
                    right = Math.max(right, list[index]);
                }
                if (valid && isBetter(left, right, bestLeft, bestRight)) {
                    bestLeft = left;
                    bestRight = right;
                }
            }
        }
        return new int[]{bestLeft, bestRight};
    }

    private int lowerBound(int[] list, int target) {
        int low = 0;
        int high = list.length;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (list[mid] < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    private boolean isBetter(int left, int right, int bestLeft, int bestRight) {
        return right - left < bestRight - bestLeft
                || (right - left == bestRight - bestLeft && left < bestLeft);
    }
}

class Solution {
    public int[] smallestRange(int[][] nums) {
        int k = nums.length;
        int[] indices = new int[k];
        int bestLeft = 0;
        int bestRight = Integer.MAX_VALUE;

        while (true) {
            int minList = 0;
            int currentMin = Integer.MAX_VALUE;
            int currentMax = Integer.MIN_VALUE;

            for (int i = 0; i < k; i++) {
                int value = nums[i][indices[i]];
                if (value < currentMin) {
                    currentMin = value;
                    minList = i;
                }
                currentMax = Math.max(currentMax, value);
            }

            if (isBetter(currentMin, currentMax, bestLeft, bestRight)) {
                bestLeft = currentMin;
                bestRight = currentMax;
            }

            indices[minList]++;
            if (indices[minList] == nums[minList].length) {
                break;
            }
        }
        return new int[]{bestLeft, bestRight};
    }

    private boolean isBetter(int left, int right, int bestLeft, int bestRight) {
        return right - left < bestRight - bestLeft
                || (right - left == bestRight - bestLeft && left < bestLeft);
    }
}
